import datetime, hashlib, json, pathlib, re
base = pathlib.Path('products/services/fr-boamp-public-docs-link-qa')
raw = (base / 'raw/official-search.json').read_bytes()
assert hashlib.sha256(raw).hexdigest() == '595fca1ee2ff8919fc51aadbec2489cd166e4458a17a6209adcdbf176dc37c9b'
feed = json.loads(raw)
cutoff = datetime.date(2026, 11, 23)
pattern = re.compile(r'audit.{0,35}liens?|liens? (?:brisés?|cassés?|morts?|rompus?)|redirections?|contrôle.{0,30}liens?', re.I)
rows = []
for record in feed['results']:
    visible = {k: v for k, v in record.items() if isinstance(v, str) and re.search(r'objet|intitul|titre|descrip|résum|resume', k, re.I)}
    dates = {k: v for k, v in record.items() if isinstance(v, str) and re.search(r'limite|deadline', k, re.I)}
    date_states = {}
    for key, value in dates.items():
        try:
            date = datetime.date.fromisoformat(value[:10])
        except ValueError:
            date_states[key] = 'unparsed'
        else:
            date_states[key] = 'past' if date < cutoff else 'same day, verify time' if date == cutoff else 'future date, verify original'
    hits = []
    for key, value in visible.items():
        match = pattern.search(value)
        if match:
            hits.append({'field': key, 'excerpt': ' '.join(value[max(0, match.start() - 45):match.end() + 65].split())})
    rows.append({'notice_id': record.get('idweb') or record.get('id'), 'deadline_fields': dates, 'deadline_screen': date_states, 'scope_fields_read': list(visible), 'scope_excerpts': hits})
report = {'source_sha256': hashlib.sha256(raw).hexdigest(), 'screen_date_utc': cutoff.isoformat(), 'reported_total': feed.get('total_count'), 'records_screened': len(rows), 'rows': rows, 'limitation': 'Screen of saved API summary fields only. Missing fields or expressions do not exclude a notice. A match does not establish a standalone lot, live deadline, supplier eligibility, or payment terms.'}
output = base / 'director-deadline-scope-screen.json'
with output.open('x', encoding='utf-8') as handle:
    json.dump(report, handle, ensure_ascii=False, indent=2)
assert json.loads(output.read_text(encoding='utf-8')) == report
print(json.dumps({'artifact': str(output), 'records_screened': len(rows), 'records_with_scope_excerpts': sum(bool(row['scope_excerpts']) for row in rows)}, ensure_ascii=False))
